/* generated by scripts/lib/scroll-concepts-studies.mjs from src/data; do not edit by hand */
window.STUDIES_FULL = {"ivy-park":{"slug":"ivy-park","title":"Ivy Park by Beyoncé","category":{"label":"Creative","href":"/category/creative"},"subtitle":"The Ivy Park launch for Nordstrom, the exclusive US partner. | Six weeks from moodboard to live, and most of the product gone within days.","field":"Creative Direction\nCampaign Design\nExperience Design\nEcommerce Design","author":"Jeremy Prasatik","published":"2016","status":"Complete","classification":["Creative Direction","Campaign Design","Experience Design","Copywriting","Ecommerce Design"],"services":["Creative Direction","Campaign Design","Experience Design","Copywriting","Ecommerce Design"],"stack":["Nordstrom CMS","Custom Components","HTML/CSS/JS"],"links":[],"heroImage":"","style":"pressing","sections":[{"id":"meta","type":"meta","reel":{"caption":"Preview · 8 frames","colors":["#1B1B1B","#605D5C","#363D45","#B4B4B4","#B9B9B9"],"images":["/case-studies/ivy-park/ivy-park-nordstrom-laptop-brand-experience-mockup.jpg","/case-studies/ivy-park/ivy-park-campaign-assets-grid-overview.jpg","/case-studies/ivy-park/ivy-park-scrolling-experience-polygon-typography.jpg","/case-studies/ivy-park/ivy-park-experience-page-hero-product-grid.jpg","/case-studies/ivy-park/ivy-park-experience-confidence-strength-inclusivity.jpg","/case-studies/ivy-park/ivy-park-experience-courage-power-polygon-frames.jpg","/case-studies/ivy-park/ivy-park-nordstrom-mobile-experience-mockup.jpg","/case-studies/ivy-park/ivy-park-product-detail-leggings-choice-system.jpg"]},"title":"Ivy Park\nby Beyoncé","subtitle":"The Ivy Park launch for Nordstrom, the exclusive US partner. | Six weeks from moodboard to live, and most of the product gone within days.","field":"Creative Direction  Campaign Design  Experience Design","author":"Jeremy Prasatik","published":"2016","status":"Complete","classification":["Creative Direction","Campaign Design","Experience Design","Copywriting"],"summary":[{"label":"Built","value":"Scrolling brand experience, launch emails, social, in-store signage"},{"label":"Scope","value":"Creative direction, experience design, copywriting"},{"label":"Stack","value":"Nordstrom CMS, custom components, HTML/CSS/JS"},{"label":"Angle","value":"No other US retailer had the product, so this website was the launch. Six weeks, with the photography supplied and everything else open."}],"abstract":"Beyoncé's first activewear line. Nordstrom had the exclusive US partnership, so this page had to be the store, the lookbook and the campaign at the same time.\n\nFour weeks for moodboards, wireframes and a concept pitch, then two weeks to build and ship. The brief came in under NDA before the team had cleared their schedules, and there were daily calls with Ivy Park while the direction locked. The photography was supplied, black-and-white athlete portraits and color product on blue and gray, and everything else was open: typography, layout, copy, animation, interaction.\n\nThe polygon showed up during concepting as a way to break the rectangular grid the photography came in. Angled, rotated and animated on scroll, it ran from the hero banner through the product carousels into the email headers. The custom CMS components built for the project went into Nordstrom's shared library and powered other launches for two years. 95% of the product sold out within days."},{"id":"hero","type":"hero","image":"/case-studies/ivy-park/ivy-park-nordstrom-laptop-brand-experience-mockup.jpg","alt":"Ivy Park by Beyoncé, Nordstrom brand experience on laptop, concrete surface","pressing":{"choreo":{"rise":true}}},{"id":"brief-header","type":"section-header","label":"SECTION 02: THE BRIEF","title":"Beyoncé's first activewear brand.","pressing":{"mark":{"n":"02","name":"The Brief"},"heldLine":"Six weeks to launch it.","choreo":{"pin":true}},"group":{"name":"brief","bg":"#ECE6E1","radius":75,"padding":"60px"}},{"id":"brief-footnote","type":"text","size":"base","fullWidth":true,"content":"Ivy Park was staking out a spot between luxury fashion and athletic performance, and there was no obvious reference for it. The design had to sit in that gap.","group":{"name":"brief"}},{"id":"brief-columns","type":"three-column-text","columns":[{"title":"The Timeline","content":"Week one: references, moodboards, competitive audit. Weeks two through four: wireframes, design concepts, copywriting, motion studies, all of it presented to Beyoncé's creative team, revisions turned around overnight. Weeks five and six: build and ship."},{"title":"The Freedom","content":"The portraits came editorial in tone, with range across body types and ethnicities. Everything around them was open territory.\n\nSo the type went larger than expected, motion lived in every scroll position, and the photography got space around it."},{"title":"The Scope","content":"One scrolling brand experience. Launch emails timed to the drop. Digital marketing across Nordstrom's owned channels, social cut for each platform, in-store signage for the locations carrying the line.\n\nAll of it built from the same handful of elements."}],"group":{"name":"brief"}},{"id":"campaign-grid","type":"hero","image":"/case-studies/ivy-park/ivy-park-campaign-assets-grid-overview.jpg","alt":"Ivy Park campaign assets grid: brand experience, emails, social, product photography, editorial","inline":true,"pressing":{"plate":"02","captions":["Campaign assets","Experience, email, social","Product and editorial"],"instruction":"Scroll. It fills the mat, then travels the frame","choreo":{"zoom":true}}},{"id":"experience-header","type":"section-header","label":"SECTION 03: THE EXPERIENCE","title":"The hexagon started as a way","pressing":{"mark":{"n":"03","name":"The Polygon"},"heldLine":"to cut portraits out of a grid.","choreo":{"pin":true,"crossing":true}}},{"id":"experience-text","type":"text","size":"subhead","content":"Every photo came in as a rectangle. Then the shape was on everything."},{"id":"experience-footnote","type":"text","size":"base","fullWidth":true,"content":"Angled edges against straight photography gave the athlete portraits some tension. Then the shape ended up doing the framing, the motion and the signature all at once."},{"id":"experience-columns","type":"three-column-text","columns":[{"title":"The Polygon","content":"A hexagonal frame, sometimes cropped tight to a jawline, sometimes open wide enough for a full figure.\n\nOn scroll it rotated slowly, which gave the flat photography some depth. It was one CSS transform."},{"title":"Typography at Volume","content":"\"Confidence is Strength.\" The type ran big, and the copy got written during production, line by line, as the pages took shape. Short lines in the present tense, talking straight to the reader."},{"title":"CMS Legacy","content":"The experience needed components Nordstrom's CMS didn't have: parallax modules, animated polygon masks, full-bleed video that played on scroll, type lockups that scaled with the screen.\n\nSo they got built, and they stayed in the CMS after the launch."}]},{"id":"experience-hex-frame","type":"hex-polygon"},{"id":"experience-page-1","type":"image","src":"/case-studies/ivy-park/ivy-park-scrolling-experience-polygon-typography.jpg","alt":"Ivy Park scrolling experience detail, polygon portrait frames, Courage is Power typography","aspect":"native","pressing":{"choreo":{"rise":true}}},{"id":"experience-polygon-lattice","type":"polygon-lattice"},{"id":"experience-screens","type":"triple-image","native":true,"images":[{"src":"/case-studies/ivy-park/ivy-park-experience-page-hero-product-grid.jpg","alt":"Ivy Park brand experience, full page hero section and product grid"},{"src":"/case-studies/ivy-park/ivy-park-experience-confidence-strength-inclusivity.jpg","alt":"Ivy Park experience, Confidence is Strength section, product specs, inclusivity messaging"},{"src":"/case-studies/ivy-park/ivy-park-experience-courage-power-polygon-frames.jpg","alt":"Ivy Park experience, Courage is Power section with polygon portrait frames"}],"pressing":{"captions":["Hero and product grid","Confidence is Strength","Courage is Power"],"choreo":{"pin":true}}},{"id":"mobile-hero","type":"hero","image":"/case-studies/ivy-park/ivy-park-nordstrom-mobile-experience-mockup.jpg","alt":"Ivy Park mobile experience on iPhone, Courage is Power section, concrete surface","inline":true,"pressing":{"choreo":{"rise":true}}},{"id":"headline-polygon","type":"editorial-headline","text":"For everybody\nand every body"},{"id":"brand-system","type":"brand-system-volume","label":"SECTION 04: BRAND SYSTEM","title":"Palette, type and shape,\nall decided during production.","introText":"Nothing came with it except the photography and the name. No palette, no type, no rules.","footText":"The visual language got worked out while the page itself came together. The polygon, the type set at volume, the scroll that ran from grayscale into color.","philosophyHeading":"The System","philosophyText":"There was never a master file. It stayed consistent because the group building it was small and didn't change.\n\nWhat follows is the working kit: the letterform behind the logo, the colors as they ran, the type at full volume, and the shape the identity leaned on.","roleLines":[{"name":"The Polygon","role":"Signature device","description":"No lockup rules and no clear-space diagram. Repetition stood in for a guide."},{"name":"Type at Volume","role":"Voice","description":"Big type, mixed weights, baselines knocked off the grid, loud enough to sit beside the photography."}],"morphGlyphs":[{"char":"I","font":"avenir-bold"},{"char":"V","font":"avenir-bold"},{"char":"Y","font":"avenir-bold"}],"colors":[{"name":"Signal","hex":"#18A6CC","rgb":"24 166 204"},{"name":"Neutral","hex":"#8E9499","rgb":"142 148 153"},{"name":"Ground","hex":"#0E0E0E","rgb":"14 14 14"}],"fonts":[{"name":"Avenir Next","role":"One face, four cuts","weights":[500,600,700,800]}],"specimenWords":["IVY","Confidence","Strength","Courage","POWER","Everybody"],"elements":{"label":"The Polygon","caption":"Signature device","sides":6},"patternLibrary":["/case-studies/ivy-park/ivy-signage.jpg","/case-studies/ivy-park/ivy-park-nordstrom-mobile-experience-mockup.jpg","/case-studies/ivy-park/ivy-park-nordstrom-laptop-brand-experience-mockup.jpg","/case-studies/ivy-park/ivy-park-campaign-assets-grid-overview.jpg"],"patternLibraryLabel":"Surfaces","patternLibraryCaption":"Four of them","typeComposition":{"ghostWord":"IVY","thinLead":"Confidence is ","heavyWord":"Strength","lockupTop":"Courage is","lockupVertical":"POWER","note":"The same voice at 12px in an email subject line and at 200px across a scrolling hero."}},{"id":"campaign-header","type":"section-header","label":"SECTION 05: THE CAMPAIGN","title":"The page came first, and everything\nelse was adapted from it.","pressing":{"mark":{"n":"04","name":"The Campaign"},"choreo":{"pin":true}}},{"id":"campaign-text","type":"text","size":"subhead","content":"Emails, banners, social, in-store signage."},{"id":"campaign-footnote","type":"text","size":"base","fullWidth":true,"content":"That worked because the elements were simple. A polygon crops the same at 300px and at 3000px, bold type reads at any size, and black-and-white photography goes to any aspect ratio."},{"id":"campaign-signage","type":"image","src":"/case-studies/ivy-park/ivy-signage.jpg","alt":"Ivy Park 'Confidence is Strength' typography system on a transit signage mockup","aspect":"native","pressing":{"choreo":{"rise":true}}},{"id":"campaign-screens","type":"triple-image","native":true,"images":[{"src":"/case-studies/ivy-park/ivy-park-product-detail-leggings-choice-system.jpg","alt":"Ivy Park product detail, leggings specification, Choice is Everything, I/V/Y rise system"},{"src":"/case-studies/ivy-park/ivy-park-shop-the-look-editorial-grid.jpg","alt":"Ivy Park Shop the Look section, editorial product grid, model portraits"},{"src":"/case-studies/ivy-park/ivy-park-editorial-beanie-portrait-dancer.jpg","alt":"Ivy Park editorial, black and white beanie portrait and dancer movement"}]},{"id":"blast-radius","type":"campaign-blast-radius"},{"id":"closing-header","type":"section-header","label":"SECTION 06: CLOSING","title":"95% of the product\nwas gone in days.","pressing":{"mark":{"n":"05","name":"Sold Out"}}},{"id":"closing-text","type":"text","size":"subhead","content":"Live in six weeks."},{"id":"closing","type":"closing","services":["Creative Direction","Campaign Design","Experience Design","Copywriting"],"stack":["Nordstrom CMS","Custom Components","HTML/CSS/JS"],"links":[],"content":"The creative direction, typography, layout, motion, copy and rollout all happened in a Nordstrom office, with a small team and a hard deadline. The brief was open, and the deadline was six weeks.\n\nAfter launch, Beyoncé sent the team a personal thank-you video. That part stays off social."}],"dims":{"/case-studies/ivy-park/ivy-park-nordstrom-laptop-brand-experience-mockup.jpg":[3080,1864],"/case-studies/ivy-park/ivy-park-campaign-assets-grid-overview.jpg":[3120,3056],"/case-studies/ivy-park/ivy-park-scrolling-experience-polygon-typography.jpg":[2188,4031],"/case-studies/ivy-park/ivy-park-experience-page-hero-product-grid.jpg":[564,1314],"/case-studies/ivy-park/ivy-park-experience-confidence-strength-inclusivity.jpg":[564,1314],"/case-studies/ivy-park/ivy-park-experience-courage-power-polygon-frames.jpg":[564,1314],"/case-studies/ivy-park/ivy-park-nordstrom-mobile-experience-mockup.jpg":[3108,2074],"/case-studies/ivy-park/ivy-park-product-detail-leggings-choice-system.jpg":[564,1314],"/case-studies/ivy-park/ivy-signage.jpg":[2300,3450],"/case-studies/ivy-park/ivy-park-shop-the-look-editorial-grid.jpg":[564,1314],"/case-studies/ivy-park/ivy-park-editorial-beanie-portrait-dancer.jpg":[564,1314]}},"hill-country-kitchen":{"slug":"hill-country-kitchen","title":"Hill Country Kitchen","category":{"label":"Interiors","href":"/category/interiors"},"subtitle":"A kitchen in the Texas Hill Country, designed around four materials. | Sage green cabinetry, raw white oak, veined marble, unlacquered brass. New and vintage together, in the same four finishes.","field":"Interior Design\nKitchen Design\nMaterial Specification","author":"Jeremy Prasatik","published":"2023","status":"Complete","classification":["Interior Design","Kitchen Design","Material Specification","Custom Millwork"],"services":["Interior Design","Space Planning","Material Specification","Construction Documentation","Fixture Selection"],"stack":["AutoCAD","SketchUp","Adobe Creative Suite"],"links":[],"heroImage":"","style":"pressing","sections":[{"id":"meta","type":"meta","reel":{"caption":"Preview · 8 frames","colors":["#35412B","#585D3E","#C1B7A9","#A99D8E","#372810"],"images":["/case-studies/hill-country-kitchen/hill-country-kitchen-island-pendants-marble-wide.jpg","/case-studies/hill-country-kitchen/hill-country-kitchen-glass-cabinet-clock-marble.jpg","/case-studies/hill-country-kitchen/hill-country-kitchen-full-view-beams-runner-island.jpg","/case-studies/hill-country-kitchen/hill-country-kitchen-sink-corner-shelves-marble.jpg","/case-studies/hill-country-kitchen/hill-country-kitchen-pantry-wall-herringbone-pendant.jpg","/case-studies/hill-country-kitchen/hill-country-kitchen-marble-backsplash-sink-detail.jpg","/case-studies/hill-country-kitchen/hill-country-kitchen-range-stove-brass-knobs-marble.jpg","/case-studies/hill-country-kitchen/hill-country-kitchen-faucet-range-marble-island-detail.jpg"]},"title":"Hill Country\nKitchen","subtitle":"A kitchen in the Texas Hill Country, designed around four materials. | Sage green cabinetry, raw white oak, veined marble, unlacquered brass. New and vintage together, in the same four finishes.","field":"Interior Design  Kitchen Design  Material Specification","author":"Jeremy Prasatik","published":"2023","status":"Complete","classification":["Interior Design","Kitchen Design","Material Specification","Custom Millwork"],"summary":[{"label":"Built","value":"Hill Country kitchen, ground up. Cabinetry, island, dining area, the full material spec."},{"label":"Scope","value":"Interior design, space planning, fixture selection, construction documentation."},{"label":"Materials","value":"Sage green, raw white oak, Calacatta marble, unlacquered brass."},{"label":"Angle","value":"Pick four materials up front and use nothing else, so pieces from different eras can share a room."}],"abstract":"Four materials, picked before the first cabinet was drawn and used on every surface. Sage green on most of what you see, raw white oak for the warmth, Calacatta marble on the counters and the backsplash, unlacquered brass on the pulls, the knobs, and the faucet. Between them they cover every cabinet face, countertop, and piece of hardware in the room.\n\nThe mix of periods is on purpose. Shaker cabinet doors come out of traditional American kitchens, the steel-frame windows and open shelving are contemporary, the cremone bolts and schoolhouse pendants are European antique, and a turned-leg dining table sits with leather safari chairs. It works as one room because all of it is in the same four finishes.\n\nThe kitchen is the hub of the house, used for cooking, gathering, and working in about equal measure. The island sits in the middle with open shelving at one end, seating at the other, and marble running the full length. Every decision came back to how a family uses a kitchen day to day."},{"id":"hero","type":"hero","image":"/case-studies/hill-country-kitchen/hill-country-kitchen-island-pendants-marble-wide.jpg","alt":"Hill Country kitchen, sage green cabinetry with marble backsplash, white oak island, brass pendants","pressing":{"choreo":{"rise":true}}},{"id":"material-header","type":"section-header","label":"SECTION 02: THE MATERIAL SYSTEM","title":"Designed around","pressing":{"mark":{"n":"02","name":"Material Selections"},"heldLine":"the material selections.","choreo":{"pin":true}},"group":{"name":"materials","bg":"#ECE6E1","radius":75,"padding":"60px"}},{"id":"material-text","type":"text","size":"subhead","content":"If it isn't sage, oak, marble or brass, it isn't in the room.","group":{"name":"materials"}},{"id":"material-footnote","type":"text","size":"base","fullWidth":true,"content":"With only four materials, each one does more of the work, and what you notice is where they meet: oak against green, marble between the two, brass on all of it.","group":{"name":"materials"}},{"id":"material-columns","type":"three-column-text","columns":[{"title":"Sage Green","content":"A muted sage with enough gray to keep it calm and enough green to keep it alive, on everything around the perimeter: base cabinets, uppers, the glass-front display, the range hood surround, the refrigerator panel, the pantry wall. It sits back a little so the marble and the brass get noticed first.\n\nThe finish is matte. Satin would have pushed the cabinets contemporary and gloss would have fought the raw oak. Matte lets the shaker profiles throw soft shadows."},{"title":"White Oak + Marble","content":"The island is raw white oak, unsealed, with the growth rings showing on the end grain of the open shelves. It is the warmest thing in the room.\n\nCalacatta marble runs the perimeter counters and the full backsplash behind the range, gray and gold veining on a warm white ground. It separates the green cabinets from the white walls, and where the oak meets the green, marble sits between them."},{"title":"Unlacquered Brass","content":"Cabinet pulls, the cremone bolts on the tall pantry doors, the bridge faucet, the pendants, the sconce arms, the range knobs and trim, all in the same brass. Even the bar stool frames pick up the tone.\n\nUnlacquered means it patinas. It darkens where hands go and stays bright where they don't, so the decorative bolts stay pale."}],"group":{"name":"materials"}},{"id":"cabinet-pair","type":"dual-image","native":true,"left":{"src":"/case-studies/hill-country-kitchen/hill-country-kitchen-glass-cabinet-clock-marble.jpg","alt":"Glass-front cabinet with brass hardware, vintage clock, marble counter"},"right":{"src":"/case-studies/hill-country-kitchen/hill-country-kitchen-full-view-beams-runner-island.jpg","alt":"Full kitchen view with exposed beams, runner rug, white oak island"}},{"id":"cabinet-wide-pair","type":"dual-image","native":true,"left":{"src":"/case-studies/hill-country-kitchen/hill-country-kitchen-sink-corner-shelves-marble.jpg","alt":"Sink corner with open shelving, marble backsplash, brass faucet"},"right":{"src":"/case-studies/hill-country-kitchen/hill-country-kitchen-pantry-wall-herringbone-pendant.jpg","alt":"Pantry wall with sage green cabinetry, herringbone floor, pendant light"},"pressing":{"captions":["Sink corner\nOpen shelves","Pantry wall, herringbone"],"choreo":{"pin":true}}},{"id":"hero-marble","type":"hero","image":"/case-studies/hill-country-kitchen/hill-country-kitchen-marble-backsplash-sink-detail.jpg","alt":"Marble backsplash detail with brass sconces, farmhouse sink, sage green cabinetry","inline":true,"pressing":{"choreo":{"rise":true}}},{"id":"hardware-header","type":"section-header","label":"SECTION 03: CABINETRY / HARDWARE","title":"Brass on everything","pressing":{"mark":{"n":"03","name":"Shaker Cabinets"},"heldLine":"you actually touch.","choreo":{"crossing":true}}},{"id":"hardware-text","type":"text","size":"subhead","content":"Floor to ceiling on three walls: base cabinets, glass-front uppers, a built-in hutch either side of the range, and full-height pantry doors that close with cremone bolts."},{"id":"hardware-footnote","type":"text","size":"base","fullWidth":true,"content":"The cremone bolts are a French mechanism on American shaker doors in a Texas kitchen. They put a long vertical line on the tallest cabinet faces and give the pantry wall a presence a standard pull wouldn't, and one lever locks the door top and bottom at once."},{"id":"range-detail","type":"image","src":"/case-studies/hill-country-kitchen/hill-country-kitchen-range-stove-brass-knobs-marble.jpg","alt":"Professional range with brass knobs, marble backsplash, sage green cabinetry","aspect":"native","padded":true,"pressing":{"choreo":{"rise":true}}},{"id":"detail-pair","type":"dual-image","native":true,"left":{"src":"/case-studies/hill-country-kitchen/hill-country-kitchen-faucet-range-marble-island-detail.jpg","alt":"Bridge faucet and range detail, marble island countertop"},"right":{"src":"/case-studies/hill-country-kitchen/hill-country-kitchen-marble-vase-cabinet-vignette.jpg","alt":"Marble counter vignette with dried arrangement, glass cabinet, brass hardware"},"pressing":{"choreo":{"pin":true}}},{"id":"hardware-closeup","type":"image","src":"/case-studies/hill-country-kitchen/hill-country-kitchen-brass-cremone-bolt-closeup.jpg","alt":"Unlacquered brass cremone bolt detail on sage green cabinet door","aspect":"native","padded":true,"pressing":{"choreo":{"rise":true}}},{"id":"pantry-hero","type":"hero","image":"/case-studies/hill-country-kitchen/hill-country-kitchen-pantry-fridge-pendant-window.jpg","alt":"Pantry wall with sage green floor-to-ceiling cabinetry, stainless refrigerator, pendant light","inline":true,"pressing":{"plate":"03","captions":["Pantry wall","Floor-to-ceiling sage cabinetry","Brass, oak, marble, sage"],"instruction":"Scroll. It fills the mat, then travels the frame","choreo":{"zoom":true}}},{"id":"headline-system","type":"editorial-headline","text":"The whole room is\nfour materials"},{"id":"material-circos","type":"material-circos"},{"id":"island-header","type":"section-header","label":"SECTION 04: THE ISLAND","title":"The marble top runs the full length","pressing":{"mark":{"n":"04","name":"Raw Oak Island"},"heldLine":"with no break in it.","choreo":{"pin":true}}},{"id":"island-text","type":"text","size":"subhead","content":"Prep counter at one end, bar at the other. Four stools with brass-tone frames tuck under the overhang."},{"id":"island-footnote","type":"text","size":"base","fullWidth":true,"content":"Open shelves on the working end keep plates and bowls within reach of the dishwasher. A firewood cubby at the base."},{"id":"island-columns","type":"three-column-text","columns":[{"title":"The Oak Choice","content":"White oak, no stain and no polyurethane, just a penetrating oil finish. The grain stays open and the color goes from pale honey to a deeper amber over years of use.\n\nRaw wood in a kitchen was the riskiest call of the whole spec. It is meant to age. The island should look used: water rings, knife marks, flour in the grain."},{"title":"Where It Sits","content":"Centered, with space to walk on all four sides, and the first thing you see from the entry. Eight feet of usable counter, with the open shelving facing the dining side.\n\nEvery sight line in the kitchen crosses it. From the range you look over it to the windows; from the dining table you look through it to the backsplash. The oak breaks up the green and marble around the perimeter."},{"title":"On Legs","content":"The island has legs, visible ones, with open shelving between them, and that is why it looks like furniture instead of a built-in. The cabinets around the walls are architecture and the island is a table.\n\nPeople treat furniture differently. Guests lean on it, sit around it, set things down on it without asking. A solid-panel island with a granite overhang would keep them at arm's length."}]},{"id":"brass-hero","type":"image","src":"/case-studies/hill-country-kitchen/hill-country-kitchen-brass-cremone-bolt-cabinet-detail.jpg","alt":"Brass cremone bolt and cabinet hardware detail on sage green panels","aspect":"native","padded":true,"pressing":{"choreo":{"rise":true}}},{"id":"hero-dining","type":"hero","image":"/case-studies/hill-country-kitchen/hill-country-kitchen-wide-dining-island-windows.jpg","alt":"Full kitchen view with dining table, island, sage green cabinetry, steel-frame windows","inline":true,"pressing":{"plate":"04","captions":["The whole room","Dining table to range wall","Both zones, one frame"],"choreo":{"zoom":true}}},{"id":"dining-header","type":"section-header","label":"SECTION 05: THE DINING ZONE","title":"The switch in tone","pressing":{"mark":{"n":"05","name":"The Dining Table"},"heldLine":"is abrupt on purpose.","choreo":{"pin":true}}},{"id":"dining-text","type":"text","size":"subhead","content":"The dining end shares the open room but goes deeper: a dark-stained table against the light oak and green of the kitchen."},{"id":"dining-footnote","type":"text","size":"base","fullWidth":true,"content":"The safari chairs are leather on oak frames. The leather picks up the warmth of the brass and the oak goes with the island. A dark patterned rug sits under the whole group and marks it off from the kitchen floor."},{"id":"dining-pair","type":"dual-image","native":true,"left":{"src":"/case-studies/hill-country-kitchen/hill-country-kitchen-dining-table-leg-rug-detail.jpg","alt":"Dining table turned leg detail on dark patterned rug"},"right":{"src":"/case-studies/hill-country-kitchen/hill-country-kitchen-dining-chair-leather-detail.jpg","alt":"Safari dining chair, leather back, natural oak frame"},"pressing":{"choreo":{"pin":true}}},{"id":"dining-full","type":"image","src":"/case-studies/hill-country-kitchen/hill-country-kitchen-dining-table-chairs-full.jpg","alt":"Full dining table with leather safari chairs on dark patterned rug","aspect":"native","padded":true,"pressing":{"choreo":{"rise":true}}},{"id":"kitchen-palette","type":"kitchen-palette"},{"id":"headline-room","type":"editorial-headline","text":"A year in, the brass shows\nwhich drawers get used"},{"id":"closing-header","type":"section-header","label":"SECTION 06: CLOSING","title":"Nothing in the room is","pressing":{"mark":{"n":"06","name":"The Hub"},"heldLine":"set aside for one job."}},{"id":"closing-text","type":"text","size":"subhead","content":"Cooking, then gathering, then working, in the same room over a day."},{"id":"closing","type":"closing","services":["Interior Design","Space Planning","Material Specification","Construction Documentation","Fixture Selection"],"stack":["AutoCAD","SketchUp","Adobe Creative Suite"],"links":[],"content":"Sage green on the vertical planes, marble on the horizontal ones, oak in the middle, brass on the hardware. The island handles prep, serving, and seating at the same time, and the dining table sits close enough to stay in the conversation and far enough off to be its own place."}],"dims":{"/case-studies/hill-country-kitchen/hill-country-kitchen-island-pendants-marble-wide.jpg":[3080,2134],"/case-studies/hill-country-kitchen/hill-country-kitchen-glass-cabinet-clock-marble.jpg":[1104,1654],"/case-studies/hill-country-kitchen/hill-country-kitchen-full-view-beams-runner-island.jpg":[1100,1654],"/case-studies/hill-country-kitchen/hill-country-kitchen-sink-corner-shelves-marble.jpg":[1092,1638],"/case-studies/hill-country-kitchen/hill-country-kitchen-pantry-wall-herringbone-pendant.jpg":[1094,1640],"/case-studies/hill-country-kitchen/hill-country-kitchen-marble-backsplash-sink-detail.jpg":[3080,2052],"/case-studies/hill-country-kitchen/hill-country-kitchen-range-stove-brass-knobs-marble.jpg":[2220,2112],"/case-studies/hill-country-kitchen/hill-country-kitchen-faucet-range-marble-island-detail.jpg":[1099,1105],"/case-studies/hill-country-kitchen/hill-country-kitchen-marble-vase-cabinet-vignette.jpg":[1099,1105],"/case-studies/hill-country-kitchen/hill-country-kitchen-brass-cremone-bolt-closeup.jpg":[2221,1105],"/case-studies/hill-country-kitchen/hill-country-kitchen-pantry-fridge-pendant-window.jpg":[3080,2052],"/case-studies/hill-country-kitchen/hill-country-kitchen-brass-cremone-bolt-cabinet-detail.jpg":[2220,1480],"/case-studies/hill-country-kitchen/hill-country-kitchen-wide-dining-island-windows.jpg":[3080,2052],"/case-studies/hill-country-kitchen/hill-country-kitchen-dining-table-leg-rug-detail.jpg":[1099,1105],"/case-studies/hill-country-kitchen/hill-country-kitchen-dining-chair-leather-detail.jpg":[1099,1105],"/case-studies/hill-country-kitchen/hill-country-kitchen-dining-table-chairs-full.jpg":[2221,1606]}},"robert-rodriguez":{"slug":"robert-rodriguez","title":"Robert Rodriguez x Neiman’s","category":{"label":"Creative","href":"/category/creative"},"subtitle":"A spring campaign for Neiman Marcus, shot in one day and run across social, email, the stores, and editorial. | ’80s mall glam meets high fashion.","field":"Campaign Design Art Direction Photo Compositing","author":"Jeremy Prasatik","published":"2024","status":"Complete","classification":["Art Direction","Photo Compositing","Typography Design","Campaign"],"services":["Art Direction","Photo Compositing","Typography Design","Campaign Design"],"stack":["Adobe Photoshop","Adobe Illustrator","Capture One"],"links":[{"label":"Neiman Marcus","url":"https://www.neimanmarcus.com"}],"heroImage":"","style":"pressing","sections":[{"id":"meta","type":"meta","title":"Robert\nRodriguez\nx\nNeiman’s","subtitle":"A spring campaign for Neiman Marcus, shot in one day and run across social, email, the stores, and editorial. | ’80s mall glam meets high fashion.","field":"Campaign Design Art Direction Photo Compositing","author":"Jeremy Prasatik","published":"2024","status":"Complete","classification":["Art Direction","Photo Compositing","Typography Design","Campaign"],"specLine":"Spring Campaign · Art Direction · Photo Compositing · Capture One","reel":{"caption":"Preview · 8 frames · Spring 2024","colors":["#E0552F","#F09A3E","#E8637A","#F5EAE7","#241C18"],"images":["/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-cream-polka-dot-dress-pink-blazer-orange-yellow-backdrop-storefront-window-display-campaign.jpg","/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-pink-blazer-beige-polka-dot-dress-orange-background-editorial-portrait.jpg","/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-model-pink-blazer-cream-polka-dot-dress-orange-red-backdrop-editorial-campaign.jpg","/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-yellow-blazer-white-pants-coral-heels-curly-hair-pink-orange-gradient-studio-editorial-portrait.jpg","/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-curly-blonde-hair-yellow-blazer-coral-pink-top-red-lipstick-studio-portrait.jpg","/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-yellow-blazer-white-pants-pink-curly-hair-colorful-gradient-overlay-portrait-concrete-wall-gallery.jpg","/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-yellow-lime-blazer-white-cropped-pants-nude-heels-studio-lookbook-portrait.jpg","/case-studies/robert-rodriguez/robert-rodriguez-logo-typography-gradient-orange-pink-coral-color-palette-branding-design.jpg"]},"pressing":{"mark":{"n":"02","name":"Statement"}}},{"id":"hero","type":"hero","image":"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-cream-polka-dot-dress-pink-blazer-orange-yellow-backdrop-storefront-window-display-campaign.jpg","alt":"Robert Rodriguez Spring — storefront window campaign display","pressing":{"choreo":{"rise":true}}},{"id":"editorial-hero-1","type":"hero","image":"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-model-pink-blazer-cream-polka-dot-dress-orange-red-backdrop-editorial-campaign.jpg","alt":"Robert Rodriguez — pink blazer editorial campaign composite","inline":true,"pressing":{"choreo":{"zoom":true},"plate":"02","captions":["Double-exposure composite","Pink blazer over mesh field","One of the four photographs"],"instruction":"Scroll. It fills the mat, then travels the frame"}},{"id":"brief-header","type":"section-header","label":"SECTION 02: THE BRIEF","title":"One shoot day stretched into","group":{"name":"brief"},"pressing":{"mark":{"n":"03","name":"The Brief"},"heldLine":"an entire campaign.","choreo":{"pin":true}}},{"id":"brief-text","type":"text","size":"subhead","content":"Neiman Marcus wanted a spring campaign for Robert Rodriguez that felt current and still kept the brand's romantic side, and the budget covered one day in the studio.","group":{"name":"brief"}},{"id":"brief-footnote","type":"text","size":"base","fullWidth":true,"content":"One model, four setups, and the photographs layered over each other so the same few pictures could carry a whole look.","group":{"name":"brief"}},{"id":"brief-columns","type":"three-column-text","group":{"name":"brief"},"pressing":{"mark":{"n":"04","name":"Method"}},"columns":[{"title":"The Reference.","content":"Mall portrait studios. Glamour Shots. The oversaturated close-up with a soft-focus background and a fan going somewhere off camera. The look of a whole decade of mall glam.\n\nThe brief was to take that energy seriously, the confidence, the color, the full unironic glamour, and rebuild it with contemporary craft."},{"title":"The Technique.","content":"Double exposures. Two frames from the same shoot layered together, one tight, one wide, and the overlap makes a third picture that neither frame has on its own. A close-up bleeds into a full-length, a gesture turns into a texture.\n\nMesh color fields replaced the airbrushed backdrops, smooth washes shifting from coral to orange to pink, with the warmth of the reference and none of the noise."},{"title":"The System.","content":"Four photographs, a typeface family, and a color field. Every piece in the campaign is some mix of those three, and each combination looks a little different from the last."}]},{"id":"portraits-dual","type":"dual-image","native":true,"left":{"src":"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-pink-blazer-beige-polka-dot-dress-orange-background-editorial-portrait.jpg","alt":"Robert Rodriguez — polka dot dress, orange backdrop"},"right":{"src":"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-pink-blazer-cream-polka-dot-ruffle-dress-orange-background-editorial-portrait.jpg","alt":"Robert Rodriguez — polka dot ruffle dress, orange backdrop"},"pressing":{"captions":["Polka-dot dress\nSpring 2024","Ruffle dress, same session"]}},{"id":"deploy-header","type":"section-header","label":"SECTION 04: CAMPAIGN / DEPLOYMENT","title":"Every piece was layered from\nthe same four pictures.","pressing":{"mark":{"n":"05","name":"Campaign & Deployment"},"choreo":{"crossing":true,"pin":true}}},{"id":"deploy-text","type":"text","size":"subhead","content":"Social got tight crops, email got the headers, the stores got the color fields at full strength, and the editorial spreads gave the double exposures room to run wide."},{"id":"deploy-footnote","type":"text","size":"base","fullWidth":true,"content":"The storefront window ran the composites at large format. The color fields were drawn as gradients, so they scale to any size. A three-foot print is as smooth as a phone screen."},{"id":"composites-dual","type":"dual-image","native":true,"left":{"src":"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-curly-blonde-hair-yellow-blazer-coral-pink-top-red-lipstick-studio-portrait.jpg","alt":"Robert Rodriguez — yellow blazer studio portrait"},"right":{"src":"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-yellow-lime-blazer-white-cropped-pants-nude-heels-studio-lookbook-portrait.jpg","alt":"Robert Rodriguez — yellow blazer lookbook portrait"},"pressing":{"captions":["Yellow blazer, studio\nSpring 2024","Lookbook"],"choreo":{"pin":true}}},{"id":"storefront-hero","type":"hero","image":"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-yellow-blazer-white-pants-coral-heels-curly-hair-pink-orange-gradient-studio-editorial-portrait.jpg","alt":"Robert Rodriguez — double-exposure editorial portrait","inline":true,"pressing":{"choreo":{"rise":true}}},{"id":"headline-glam","type":"editorial-headline","text":"The mall studio,\nrebuilt for\nthe runway","pressing":{"choreo":{"quotePoster":true},"indent":1,"mark":{"n":"06","name":"Compositing as Design System","dark":true},"navDark":true}},{"id":"brand-header","type":"section-header","label":"SECTION 05: TYPOGRAPHY / BRAND","title":"Archer Hairline is thin enough to sit","group":{"name":"brand"},"pressing":{"mark":{"n":"07","name":"Typography & Brand"},"heldLine":"over the pictures without fighting them.","choreo":{"pin":true}}},{"id":"brand-text","type":"text","size":"subhead","content":"The type was chosen for this campaign specifically. Archer Book for body copy, warm rounded serifs that match the softness of the photography.","group":{"name":"brand"}},{"id":"brand-footnote","type":"text","size":"base","fullWidth":true,"content":"The palette is coral, orange, and pink. As flat blocks they clash; with smooth transitions between them they work.","group":{"name":"brand"}},{"id":"system-index","type":"rr-system-index","pressing":{"mark":{"n":"08","name":"The System"}}},{"id":"brand-image-2","type":"image","src":"/case-studies/robert-rodriguez/robert-rodriguez-logo-typography-gradient-orange-pink-coral-color-palette-branding-design.jpg","alt":"Robert Rodriguez — logo in Archer Hairline over Book on a mesh colour field","aspect":"native","pressing":{"choreo":{"zoom":true},"plate":"08","captions":["Logo on mesh field","Hairline caps over Book lowercase","Depth through overlap"]}},{"id":"lookbook-hero","type":"hero","image":"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-yellow-blazer-white-pants-pink-curly-hair-colorful-gradient-overlay-portrait-concrete-wall-gallery.jpg","alt":"Robert Rodriguez — gallery installation with gradient overlay composite","inline":true,"pressing":{"choreo":{"rise":true}}},{"id":"closing-header","type":"section-header","label":"SECTION 06: CLOSING","title":"One day in the studio,","pressing":{"mark":{"n":"09","name":"Closing"},"heldLine":"a season on every channel."}},{"id":"closing","type":"closing","services":["Art Direction","Photo Compositing","Typography Design","Campaign Design"],"stack":["Adobe Photoshop","Adobe Illustrator","Capture One"],"links":[{"label":"Neiman Marcus","url":"https://www.neimanmarcus.com"}],"content":"The whole campaign is four photographs from one day, layered over each other and set on gradients."}],"dims":{"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-cream-polka-dot-dress-pink-blazer-orange-yellow-backdrop-storefront-window-display-campaign.jpg":[3080,2052],"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-pink-blazer-beige-polka-dot-dress-orange-background-editorial-portrait.jpg":[1520,2282],"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-model-pink-blazer-cream-polka-dot-dress-orange-red-backdrop-editorial-campaign.jpg":[3078,3078],"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-yellow-blazer-white-pants-coral-heels-curly-hair-pink-orange-gradient-studio-editorial-portrait.jpg":[3078,2570],"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-curly-blonde-hair-yellow-blazer-coral-pink-top-red-lipstick-studio-portrait.jpg":[1520,2282],"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-yellow-blazer-white-pants-pink-curly-hair-colorful-gradient-overlay-portrait-concrete-wall-gallery.jpg":[3080,2054],"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-yellow-lime-blazer-white-cropped-pants-nude-heels-studio-lookbook-portrait.jpg":[1520,2282],"/case-studies/robert-rodriguez/robert-rodriguez-logo-typography-gradient-orange-pink-coral-color-palette-branding-design.jpg":[3070,2558],"/case-studies/robert-rodriguez/neiman-marcus-robert-rodriguez-woman-pink-blazer-cream-polka-dot-ruffle-dress-orange-background-editorial-portrait.jpg":[1520,2282]}}};
